#include "tests/support/socket/document_clear_test_fixture.hpp"
using namespace clear_test;
namespace {
using G=Graph;
void links(Fixture& f,std::initializer_list<unsigned> indices,std::uintptr_t owner=State::base){
    std::vector<unsigned> list(indices);f.graph.set(owner+0x38,list.empty()?0:G::node(list.front()));f.graph.set(owner+0x40,list.empty()?0:G::node(list.back()));
    for(std::size_t i=0;i<list.size();++i){const auto n=G::node(list[i]);f.graph.set(n+0x10,owner);f.graph.set(n+0x48,i?G::node(list[i-1]):0);f.graph.set(n+0x50,i+1<list.size()?G::node(list[i+1]):0);}
}
std::vector<std::uintptr_t> receivers(const Nodes& nodes,std::string_view kind){std::vector<std::uintptr_t> result;for(const auto& c:nodes.calls)if(c.kind==kind)result.push_back(c.first);return result;}
std::uint64_t image_word(const State& state,std::size_t at,unsigned width=8){const auto bytes=state.snapshot();std::uint64_t value=0;for(unsigned i=0;i<width;++i)value|=std::uint64_t(bytes[at+i])<<(i*8);return value;}
void basic_graph(){
    {Fixture f;f.construct();f.state.put(0x40,G::node());f.delete_nodes();check(!f.state.get(0x38)&&!f.state.get(0x40)&&f.nodes.calls.empty(),"empty owner clears stale last pointer without virtual calls");}
    for(unsigned count:{1U,2U,4U}){Fixture f;f.construct();if(count==1)links(f,{0});else if(count==2)links(f,{0,1});else links(f,{0,1,2,3});f.nodes.hook=[&](auto name){if(name=="probe"){const auto node=f.nodes.calls.back().first;check(!f.graph.get(node+0x10)&&!f.graph.get(node+0x48)&&!f.graph.get(node+0x50),"node parent/previous/next cleared before probe");}};f.delete_nodes();check(!f.state.get(0x38)&&!f.state.get(0x40)&&f.nodes.probes==count&&f.nodes.destroys==count&&f.nodes.releases==count,"single/multiple list drain owner links and perform one probe/destructor/release per node");for(unsigned i=0;i<count;++i){const auto& p=f.nodes.calls[i*3];const auto& d=f.nodes.calls[i*3+1];const auto& r=f.nodes.calls[i*3+2];check(p.kind=="probe"&&p.target==0xf001&&p.first==G::node(i),"ordered probe receiver and target");check(d.kind=="destroy"&&d.target==0xf002&&d.first==G::node(i)&&!d.flags,"destructor receives node and defined zero flags");check(r.kind=="release"&&r.target==0xe001&&r.first==G::pool()&&r.second==G::node(i),"pool release forwards defined pool receiver and RDX node");}}
    {Fixture f;f.construct();links(f,{0});f.graph.set(G::node()+0x48,G::node(7));f.graph.set(G::node(7)+0x50,G::node());f.delete_nodes();check(!f.graph.get(G::node(7)+0x50)&&!f.state.get(0x40),"nonzero previous link is repaired even for last removed node");}
}
void tracking(){
    for(std::uint64_t probe:{0x100000000ULL,0x8000000000000000ULL}){Fixture f;f.construct();links(f,{0});f.nodes.probe_result=probe;f.graph.set(G::node()+8,0xdead);f.delete_nodes();check(f.nodes.destroys==1&&f.nodes.releases==1,"full64 nonzero probe bypasses tracking even when low32 is zero");}
    for(std::uint32_t count:{0U,0xffffffffU,0x80000000U}){Fixture f;f.construct();links(f,{0});f.nodes.probe_result=0;f.state.put(0x104,count,4);f.state.put(0xa8,0xdead);f.delete_nodes();check(f.state.get(0x104,4)==count&&f.nodes.releases==1,"signed nonpositive count skips tracking array dereference and decrement");}
    {Fixture f;f.construct();links(f,{0});f.nodes.probe_result=0;f.state.put(0xa8,G::tracking());f.state.put(0x104,3,4);f.graph.set(G::tracking(),G::node(8));f.graph.set(G::tracking()+8,G::node());f.graph.set(G::tracking()+16,G::node(9));f.delete_nodes();check(f.state.get(0x104,4)==2&&f.graph.get(G::tracking())==G::node(8)&&f.graph.get(G::tracking()+8)==G::node(9)&&f.graph.get(G::tracking()+16)==G::node(9),"matched tracking entry swaps last live slot then decrements without clearing dead slot");}
    {Fixture f;f.construct();links(f,{0});f.nodes.probe_result=0;f.state.put(0xa8,G::tracking());f.state.put(0x104,2,4);f.graph.set(G::tracking(),G::node(8));f.graph.set(G::tracking()+8,G::node(9));f.delete_nodes();check(f.state.get(0x104,4)==2&&f.graph.get(G::tracking())==G::node(8)&&f.graph.get(G::tracking()+8)==G::node(9),"positive tracking search not found leaves count/slots intact");}
    {Fixture f;f.construct();links(f,{0});f.nodes.probe_result=0;f.state.put(0xa8,G::tracking());f.state.put(0x104,1,4);f.graph.set(G::tracking(),G::node());f.delete_nodes();check(!f.state.get(0x104,4)&&f.graph.get(G::tracking())==G::node(),"single tracking entry leaves its dead slot while count becomes zero");}
    // Deliberately aliased bounded fields: entry0 spans document+100/+104.
    // This distinguishes the native DEC reload from a cached count-1 model.
    {Fixture f;f.construct();links(f,{0});f.nodes.probe_result=0;const auto count=G::node()>>32;check(count>1&&count<32,"bounded alias tracking anchor");f.state.put(0xa8,State::base+0x100);f.state.put(0x100,G::node());f.state.put(0x100+(count-1)*8,0x312345678ULL);f.delete_nodes();check(f.state.get(0x100,4)==0x12345678&&f.state.get(0x104,4)==2,"swap store changes aliased live DWORD to3 before DEC rereads and produces2");}
}
void live_targets_and_owner(){
    {Fixture f;f.construct();links(f,{0});f.graph.set(G::node()+0x48,G::node(7));f.graph.set(G::node(7)+0x50,G::node());f.graph.set(G::node(),G::node()+0x10);f.nodes.hook=[&](auto name){if(name=="probe"){check(f.nodes.calls.back().target==0,"probe target loaded after previous-link zero through aliased table+38");f.graph.set(G::node(),G::table());}};f.delete_nodes();check(f.nodes.releases==1,"late aliased probe target remains a mandatory effect token");}
    {Fixture f;f.construct();links(f,{0});
        // Alias logical vptr storage with parent+10, while keeping the virtual
        // address mappings disjoint. Native caches vptr before clearing+10.
        f.state.regions[450]={};f.state.regions[499]={G::node(),std::span(f.graph.node_bytes[0]).subspan(0x10,8)};f.state.regions[500]={G::node()+8,std::span(f.graph.node_bytes[0]).subspan(8)};f.graph.set(G::node(),G::table());
        f.nodes.hook=[&](auto name){if(name=="probe"){check(f.nodes.calls.back().target==0xf001&&!f.graph.get(G::node()),"cached table survives zero of aliased vptr storage before probe target load");f.graph.set(G::node(),G::table());}};f.delete_nodes();check(f.nodes.releases==1,"cached vptr alias test completes through restored live vptr");}
    {Fixture f;f.construct();links(f,{0});f.nodes.hook=[&](auto name){if(name=="probe")f.graph.set(G::node(),G::table(1));if(name=="destroy"){check(f.nodes.calls.back().target==0xf012,"destructor target reloaded from callback changed node table");f.graph.set(G::node()+0x60,G::pool(1));f.graph.set(G::pool(),G::pooltable(2));}};f.delete_nodes();const auto& release=f.nodes.calls.back();check(release.kind=="release"&&release.target==0xe021&&release.first==G::pool()&&release.second==G::node(),"pool cached before destructor but its release table read after callback; explicit RDX node preserved");}
    {Fixture f;f.construct();const auto owner=G::node(15);links(f,{0,1},owner);f.nodes.hook=[&](auto name){if(name=="release"&&f.nodes.releases==1){links(f,{2},owner);}};f.delete_nodes(owner);check(receivers(f.nodes,"destroy")==std::vector<std::uintptr_t>{G::node(),G::node(2)}&&!f.graph.get(owner+0x38)&&!f.graph.get(owner+0x40),"owner first child reloaded after release callback instead of following cached next node");check(!f.state.get(0x38)&&!f.state.get(0x40),"non-document owner is kept distinct from node document pointer");}
}
void clear_tracking(){
    {Fixture f;f.construct();f.nodes.mutate=false;f.state.put(0xa8,G::tracking());f.state.put(0x104,2,4);f.graph.set(G::tracking(),G::node());f.graph.set(G::tracking(1),G::node(1));f.graph.set(G::node()+0x10,G::node(9));f.nodes.hook=[&](auto name){if(name=="parent"){const auto& call=f.nodes.calls.back();check(call.first==G::node(9)&&call.second==G::node(),"attached branch forwards parent and original node");f.state.put(0xa8,G::tracking(1));f.state.put(0x104,1,4);}if(name=="delete")f.state.put(0x104,0,4);};f.clear();check(f.nodes.trace==std::vector<std::string>{"parent","track","delete"},"clear reloads tracking table/count and visits attached then unattached branches");check(f.nodes.calls[1].target==0xe002&&f.nodes.calls[1].first==G::pool()&&f.nodes.calls[2].first==G::node(1),"unattached track target/pool and delete node identities");check(f.graph.get(G::tracking())==G::node()&&f.graph.get(G::tracking(1))==G::node(1),"document clear itself does not erase tracking dead slots");}
    {Fixture f;f.construct();f.nodes.mutate=false;f.state.put(0xa8,G::tracking());f.state.put(0x104,1,4);f.graph.set(G::tracking(),G::node());f.nodes.hook=[&](auto name){if(name=="track"){f.graph.set(G::tracking(),G::node(1));f.state.put(0x104,0,4);}};f.clear();check(f.nodes.tracks==1&&f.nodes.deletes==1&&f.nodes.calls.back().first==G::node(),"pool-track callback changes count/table entry but cached original node is still deleted");}
    {Fixture f;f.construct();f.nodes.mutate=false;f.state.put(0xa8,G::tracking());f.state.put(0x104,0x80000000,4);f.graph.set(G::tracking(),G::node());f.graph.set(G::node()+0x10,G::node(9));f.nodes.hook=[&](auto name){if(name=="parent")f.state.put(0x104,0,4);};f.clear();check(f.nodes.parents==1&&!f.nodes.tracks&&!f.nodes.deletes,"clear tests DWORD nonzero even for negative signed count; lower callback terminates bounded fixture");}
}
void clear_fields_and_frees(){
    {Fixture f;f.construct();f.state.put(0x6c,71,4);f.state.put(0x90,72,4);f.state.put(0x78,0x200,4);f.state.put(0x80,0x1111);f.state.put(0x88,19);f.state.put(0x98,0x2222);f.state.put(0xa4,77,4);f.docs.lower.hook=[&](auto name){if(name!="free")return;if(f.docs.lower.freed.size()==1){check(!f.state.get(0x6c,4)&&!f.state.get(0x90,4)&&f.state.get(0x78,4)==0x200&&f.state.get(0x80)==0x1111&&f.state.get(0x88)==19,"error/line reset before owned free while owned string metadata still live");f.state.put(0x6c,std::uint32_t(-9),4);f.state.put(0x90,999,4);f.state.put(0x104,123,4);f.state.put(0x98,0x3333);}else{check(!f.state.get(0x78,4)&&!f.state.get(0x80)&&!f.state.get(0x88)&&f.state.get(0x98)==0x3333,"string fields reset before unconditional buffer free; live buffer pointer reloaded");f.state.put(0x98,0x4444);f.state.put(0xa4,888,4);}};f.clear();check(f.docs.lower.freed==std::vector<std::uintptr_t>{0x1111,0x3333},"owned and live parser buffers passed as pointer-only frees");check(f.document.error_6c==-9&&f.state.get(0x90,4)==999&&f.state.get(0x104,4)==123&&!f.state.get(0x98)&&!f.state.get(0xa4,4),"later free callback mutations to early error/line/count survive; only buffer/a4 reset at end");}
    for(std::uint32_t flags:{0U,0x400U,0x200U}){Fixture f;f.construct();f.state.put(0x78,flags,4);f.state.put(0x80,0);f.state.put(0x98,0);f.clear();check(f.docs.lower.freed==std::vector<std::uintptr_t>((flags&0x200)?2:1,0),"only bit200 controls owned free; parser buffer is unconditionally freed including0");}
    for(unsigned fail=1;fail<=2;++fail){Fixture f;f.construct();f.state.put(0x6c,71,4);f.state.put(0x90,72,4);f.state.put(0x78,0x200,4);f.state.put(0x80,0x1111);f.state.put(0x88,19);f.state.put(0x98,0x2222);f.state.put(0xa4,77,4);f.docs.lower.hook=[&](auto name){if(name=="free"&&f.docs.lower.freed.size()==fail)throw Failure{44};};try{f.clear();throw std::runtime_error("missing free failure");}catch(const Failure& e){check(e.code==44&&f.docs.lower.freed.size()==fail&&!f.state.get(0x6c,4)&&!f.state.get(0x90,4),"free failure keeps early error/line writes without invented subsequent free");check(f.state.get(0x98)==0x2222&&f.state.get(0xa4,4)==77,"buffer/a4 remain live when free throws");check((f.state.get(0x78,4)==0)==(fail==2)&&(f.state.get(0x80)==0)==(fail==2)&&(f.state.get(0x88)==0)==(fail==2),"string metadata resets only after successful owned free");}}
    for(const auto [at,width]:{std::pair<std::size_t,std::size_t>{0x90,4},{0x88,8}}){Fixture f;f.construct();f.state.put(0x6c,71,4);f.state.put(0x90,72,4);f.state.put(0x78,0x200,4);f.state.put(0x80,0x1111);f.state.put(0x88,19);f.state.put(0x98,0x2222);f.state.omitted={{at,width}};f.graph.refresh();try{f.clear();throw std::runtime_error("missing bounded field failure");}catch(const s::UnsupportedInput&){check(image_word(f.state,0x6c,4)==0&&image_word(f.state,0x98)==0x2222,"bounded later field failure preserves earlier reset and later untouched buffer");if(at==0x90)check(image_word(f.state,0x90,4)==72&&f.docs.lower.freed.empty()&&image_word(f.state,0x78,4)==0x200,"line-store failure precedes ownership/free/reset");else check(image_word(f.state,0x78,4)==0&&!image_word(f.state,0x80)&&image_word(f.state,0x88)==19&&f.docs.lower.freed==std::vector<std::uintptr_t>{0x1111},"count-store failure occurs after flags/pointer stores and owned free");}}
}
void failure_prefixes(){
    for(const auto stage:{"probe","destroy","release"}){Fixture f;f.construct();links(f,{0,1});f.nodes.hook=[&](auto name){if(name==stage)throw Failure{44};};try{f.delete_nodes();throw std::runtime_error("missing node effect failure");}catch(const Failure& e){check(e.code==44&&f.nodes.trace.back()==stage&&f.state.get(0x38)==G::node(1)&&f.state.get(0x40)==G::node(1),"node failure retains first-unlink owner prefix and leaves later node unprocessed");check(!f.graph.get(G::node()+0x10)&&!f.graph.get(G::node()+0x48)&&!f.graph.get(G::node()+0x50)&&!f.graph.get(G::node(1)+0x48),"node failure retains cleared node fields and repaired next previous link");check(f.nodes.probes==1&&f.nodes.destroys==unsigned(std::string_view(stage)!="probe")&&f.nodes.releases==unsigned(std::string_view(stage)=="release"),"no invented later virtual effects after failure");}}
    for(const auto stage:{"parent","track","delete"}){Fixture f;f.construct();f.nodes.mutate=false;f.state.put(0xa8,G::tracking());f.state.put(0x104,1,4);f.state.put(0x6c,71,4);f.state.put(0x90,72,4);f.graph.set(G::tracking(),G::node());if(std::string_view(stage)=="parent")f.graph.set(G::node()+0x10,G::node(9));f.nodes.hook=[&](auto name){if(name==stage)throw Failure{44};};try{f.clear();throw std::runtime_error("missing tracking lower failure");}catch(const Failure& e){check(e.code==44&&f.nodes.trace.back()==stage&&f.state.get(0x104,4)==1&&f.document.error_6c==71&&f.state.get(0x90,4)==72&&f.docs.lower.freed.empty(),"tracking lower failure precedes final field resets/frees and has no invented unwind cleanup");}}
}
}
int main(){try{basic_graph();tracking();live_targets_and_owner();clear_tracking();clear_fields_and_frees();failure_prefixes();std::cout<<"PASS: "<<checks<<" document clear checks; child graph unlink/tracking/virtual targets, cached and live callback fields, exact reset/free order and failure prefixes; native DOM/pool lower bodies and ABI/EH remain open\n";}catch(const std::exception& e){std::cerr<<"FAIL after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}catch(...){std::cerr<<"FAIL: unexpected terminal\n";return 1;}}
